COV = SP + 'covers/'
def B(*rows): return [r for r in rows]
_PQ = {e['id']: e for e in json.load(open(SP + 'Q3/passages.json', encoding='utf-8'))}
def mk(pid, keys=None, alts=None):
    """texto del pasaje con [[k:…]] y [[a:…]] alrededor de las frases clave / de matiz (la primera aparición de cada una)."""
    e = _PQ[pid]; t = e['passage']
    spans = []
    for kind, L in (('k', keys if keys is not None else e['keys']), ('a', alts if alts is not None else e['alts'])):
        for s in L:
            i = t.find(s)
            if i >= 0: spans.append((i, i + len(s), kind))
    spans.sort(); out = []; pos = 0; last_end = -1
    for a, b, kind in spans:
        if a < last_end: continue
        out.append(t[pos:a]); out.append(f'[[{kind}:{t[a:b]}]]'); pos = b; last_end = b
    out.append(t[pos:]); return ''.join(out)

